// DEMO-STORY configuration. The demo module is mounted only when BW_DEMO_MODE=1 (see ../run.ts). Dev only:
// the internal token is a demo secret written to .env.demo by scripts/demo.mjs, never a production credential.
import { z } from 'zod';

import { defineConfig, type EnvSource } from '@blackwing/config';

import { normaliseOrigin, portOf, staticClass, type OriginPolicy } from './ownership.js';

/** Minimum length of the internal token (demo secret, generated by scripts/demo.mjs). */
const MIN_TOKEN_LENGTH = 32;
/** Same variable and default as the worker (apps/worker/src/demo/main.ts); the launcher passes it to both. */
const DEFAULT_GATE2_TIMEOUT_S = 900;
/** Same variable and default as the worker (apps/worker/src/demo/main.ts): runs the hunt engine starts at once. */
export const DEFAULT_HUNT_CONCURRENCY = 3;
/** The launcher's smoke API port (scripts/blackwing.mjs SMOKE_API_PORT): also Blackwing itself, never a target. */
const SMOKE_API_PORT = 13401;
const DEFAULT_API_PORT = 3000;

/** Longest objective of an assessment request (the request schema and the clone with untried cases). */
export const OBJECTIVE_MAX = 2000;

/** Budget limits of one assessment request: the request schema validates against them, the presets are clamped to them. */
export const BUDGET_LIMITS = {
  requests: { min: 10, max: 5000 },
  minutes: { min: 1, max: 120 },
  costUsd: { min: 0.5, max: 100 },
} as const;

export interface BudgetPreset {
  readonly key: string;
  readonly label: string;
  readonly minutes: number;
  readonly requests: number;
  readonly costUsd: number;
}

const clamp = (value: number, range: { readonly min: number; readonly max: number }): number =>
  Math.min(range.max, Math.max(range.min, value));

/** The budget presets the console offers (defined once here, clamped to the limits). */
export const BUDGET_PRESETS: readonly BudgetPreset[] = [
  { key: 'quick', label: 'Quick', minutes: 10, requests: 300, costUsd: 3 },
  { key: 'standard', label: 'Standard', minutes: 30, requests: 1000, costUsd: 8 },
  { key: 'thorough', label: 'Thorough', minutes: 120, requests: 5000, costUsd: 25 },
].map((p) => ({
  ...p,
  minutes: clamp(p.minutes, BUDGET_LIMITS.minutes),
  requests: clamp(p.requests, BUDGET_LIMITS.requests),
  costUsd: clamp(p.costUsd, BUDGET_LIMITS.costUsd),
}));

const demoEnvObject = z.object({
    BW_DEMO_MODE: z.enum(['0', '1']).default('0'),
    /** Shared secret between the demo web server and this API (internal hop only). */
    BW_DEMO_INTERNAL_TOKEN: z.string().min(MIN_TOKEN_LENGTH).optional(),
    /** The workspace (tenant) the console runs in: the launcher passes the only active tenant of the database. */
    BW_DEMO_TENANT_ID: z.string().min(1).optional(),
    DATABASE_URL: z.string().min(1).optional(),
    /** Administrators' e-mails (comma separated): each holds every role and may approve its own requests. */
    BW_ADMIN_EMAILS: z.string().default(''),
    /** Optional Slack-compatible webhook: each released finding is POSTed there. Unset means no delivery. */
    BW_DEMO_WEBHOOK_URL: z.url({ protocol: /^https?$/ }).optional(),
    /** Console origin used for the finding links in the webhook message. */
    BW_CONSOLE_ORIGIN: z.string().min(1).default('http://localhost:3000'),
    /** Seconds a Gate 2 request waits for a human before it is denied (shown in the console, enforced by the worker). */
    BW_GATE2_TIMEOUT_S: z.coerce.number().int().min(1).default(DEFAULT_GATE2_TIMEOUT_S),
    /** Runs the hunt engine runs at once (the queue position the console shows is computed against it). */
    BW_HUNT_CONCURRENCY: z.coerce.number().int().min(1).default(DEFAULT_HUNT_CONCURRENCY),
    /** Operator-listed lab origins (comma list): the only private or local addresses Blackwing may test. */
    BW_LAB_ORIGINS: z.string().default(''),
    /** Blackwing's own origins and port: never a target. */
    WEB_ORIGIN: z.string().optional(),
    BW_DEMO_API_ORIGIN: z.string().optional(),
    API_PORT: z.coerce.number().int().min(1).default(DEFAULT_API_PORT),
  });

const demoEnvSchema = demoEnvObject.superRefine((env, ctx) => {
    if (env.BW_DEMO_MODE !== '1') return;
    for (const key of ['BW_DEMO_INTERNAL_TOKEN', 'BW_DEMO_TENANT_ID', 'DATABASE_URL'] as const) {
      if (env[key] === undefined) {
        ctx.addIssue({ code: 'custom', path: [key], message: `${key} is required in demo mode` });
      }
    }
    const policy = originPolicy(env);
    for (const entry of splitList(env.BW_LAB_ORIGINS)) {
      const origin = normaliseOrigin(entry);
      const refused = origin === null ? 'is not an http(s) origin' : labRefusal(origin, policy);
      if (refused !== null) {
        ctx.addIssue({ code: 'custom', path: ['BW_LAB_ORIGINS'], message: `${entry} ${refused}` });
      }
    }
  });

const splitList = (value: string): string[] =>
  value
    .split(',')
    .map((e) => e.trim())
    .filter((e) => e !== '');

function labRefusal(origin: string, policy: OriginPolicy): string | null {
  const kind = staticClass(origin, { ...policy, labOrigins: [] });
  if (kind === 'platform') return 'is Blackwing itself and can never be a lab';
  if (kind === 'forbidden') return 'is a cloud metadata or link-local address and can never be a lab';
  return null;
}

type DemoEnv = z.output<typeof demoEnvObject>;

function originPolicy(env: DemoEnv): OriginPolicy {
  const platformOrigins = [env.BW_CONSOLE_ORIGIN, env.WEB_ORIGIN, env.BW_DEMO_API_ORIGIN]
    .map((o) => (o === undefined ? null : normaliseOrigin(o)))
    .filter((o): o is string => o !== null);
  const ports = platformOrigins.map((o) => portOf(new URL(o)));
  return {
    labOrigins: splitList(env.BW_LAB_ORIGINS)
      .map((o) => normaliseOrigin(o))
      .filter((o): o is string => o !== null),
    platformOrigins,
    platformPorts: [...new Set([...ports, env.API_PORT, SMOKE_API_PORT])],
  };
}

export interface DemoConfig {
  readonly enabled: boolean;
  readonly internalToken: string;
  readonly tenantId: string;
  readonly databaseUrl: string;
  /** Lower-cased administrator e-mails (BW_ADMIN_EMAILS). */
  readonly adminEmails: readonly string[];
  readonly webhookUrl: string | null;
  readonly consoleOrigin: string;
  readonly gate2TimeoutS: number;
  readonly huntConcurrency: number;
  /** Lab allow-list and Blackwing's own origins (see ./ownership.ts). */
  readonly origins: OriginPolicy;
}

/** Reads the demo variables. Disabled (and inert) unless BW_DEMO_MODE=1. */
export function loadDemoConfig(source?: EnvSource): DemoConfig {
  const env = defineConfig(demoEnvSchema, source === undefined ? {} : { source });
  return {
    enabled: env.BW_DEMO_MODE === '1',
    internalToken: env.BW_DEMO_INTERNAL_TOKEN ?? '',
    tenantId: env.BW_DEMO_TENANT_ID ?? '',
    databaseUrl: env.DATABASE_URL ?? '',
    adminEmails: env.BW_ADMIN_EMAILS.split(',')
      .map((e) => e.trim().toLowerCase())
      .filter((e) => e !== ''),
    webhookUrl: env.BW_DEMO_WEBHOOK_URL ?? null,
    consoleOrigin: env.BW_CONSOLE_ORIGIN,
    gate2TimeoutS: env.BW_GATE2_TIMEOUT_S,
    huntConcurrency: env.BW_HUNT_CONCURRENCY,
    origins: originPolicy(env),
  };
}
